/** 
 * Creates the OpenGL surfaces. <p>This method must be called on the  {@linkplain #THREAD_NAME background thread}.
 */
@WorkerThread private void createOpenGlSurfaces(Surface outputSurface,@Nullable SurfaceView debugSurfaceView){
  checkState(Thread.currentThread().getName().equals(THREAD_NAME));
  checkStateNotNull(eglDisplay);
  try {
    if (enableExperimentalHdrEditing) {
      eglSurface=GlUtil.getEglSurfaceBt2020Pq(eglDisplay,outputSurface);
      if (debugSurfaceView != null) {
        debugPreviewEglSurface=GlUtil.getEglSurfaceBt2020Pq(eglDisplay,checkNotNull(debugSurfaceView.getHolder()));
      }
    }
   else {
      eglSurface=GlUtil.getEglSurface(eglDisplay,outputSurface);
      if (debugSurfaceView != null) {
        debugPreviewEglSurface=GlUtil.getEglSurface(eglDisplay,checkNotNull(debugSurfaceView.getHolder()));
      }
    }
  } catch (GlException e) {
    // Log the exception for debugging purposes
    Log.e("createOpenGlSurfaces", "Error creating OpenGL surfaces: " + e.getMessage(), e);
    // Optionally rethrow if the exception should propagate
    throw e;
  }
}
